using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using Newtonsoft.Json.Linq;using SpatialWallpaper.Supervision;using SpatialWallpaper.Supervision.Windows;using SpatialWallpaper.Sdk.Hosting;
static class WorkerStopChecks {
 static void Need(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Until(Func<bool> f){var watch=Stopwatch.StartNew();while(!f()){if(watch.ElapsedMilliseconds>10000)throw new TimeoutException("fixture-deadline");Thread.Sleep(2);}}
 sealed class Worker:IManagedWorker {
  internal RestrictedProcess Child;internal WorkerStopChannel Stop;internal WorkerWritePipe Ready;Thread reader;readonly Stopwatch clock;int ready;long seq;internal int Kills;internal bool Cleaned;
  internal Worker(Stopwatch c){clock=c;}
  internal void Begin(){reader=new Thread(()=>{var b=new byte[1];if(Ready.Read(b,0,1)==1&&b[0]==1)Volatile.Write(ref ready,1);}){IsBackground=true};reader.Start();}
  public int ProcessId=>Child.ProcessId;
  public WorkerSample Sample(){bool alive=Child.Wait(0)==258;return new WorkerSample(alive,1024,0,Volatile.Read(ref ready)==1?++seq:0,clock.ElapsedMilliseconds,Stop.Failed,exitCode:alive?(uint?)null:Child.ExitCode,stopPublishedAt:Stop.PublishedAt);}
  public void RequestStop()=>Stop.Request();
  public void Kill(){Kills++;Child.Kill(124);}
  public void Dispose(){if(Child.Wait(0)==258)Child.Kill(125);Need(Child.Wait(1000)==0,"fixture-kernel-exited");if(reader!=null)Need(reader.Join(1000),"fixture-reader-joined");Stop.Dispose();Ready.Dispose();Child.Dispose();Cleaned=true;}
 }
 sealed class Launcher:IWorkerLauncher {
  readonly PrivateStation station;readonly string source,output;readonly Stopwatch clock;internal Worker Last;
  internal Launcher(PrivateStation s,string src,string dst,Stopwatch c){station=s;source=src;output=dst;clock=c;}
  public IManagedWorker Start(LaunchRequest request,AttemptReceipt receipt,Action<int> created){var w=new Worker(clock);string root=Path.Combine(output,receipt.Attempt.ToString("N"));Directory.CreateDirectory(root);foreach(var f in Directory.GetFiles(source))File.Copy(f,Path.Combine(root,Path.GetFileName(f)));File.WriteAllText(Path.Combine(root,".sdk-worker-owned"),"stop fixture");var id=new WorkerIdentity(receipt.Attempt,receipt.Instance,receipt.Generation);var args=new[]{"0","0",id.Attempt.ToString(),id.Instance.ToString(),id.Generation.ToString(),request.RuntimePath};try{w.Child=RestrictedProcess.Start(station,Path.Combine(root,"Peer.exe"),args,root,256L*1024*1024,sid=>{w.Stop=new WorkerStopChannel(sid,id,()=>clock.ElapsedMilliseconds);w.Ready=new WorkerWritePipe(sid);args[0]=w.Stop.ChildReader.ToInt64().ToString();args[1]=w.Ready.ChildWriter.ToInt64().ToString();return new[]{w.Stop.ChildReader,w.Ready.ChildWriter};},pid=>{created(pid);w.Stop.CloseChildCopy();w.Ready.CloseChildCopy();},id.Attempt);w.Begin();return Last=w;}catch{w.Child?.Dispose();w.Stop?.Dispose();w.Ready?.Dispose();throw;}}
 }
 static int Main(string[] args){try{var results=new JArray();var clock=Stopwatch.StartNew();using(var station=new PrivateStation()){var journal=new JournalActor(Path.Combine(args[1],"journal"),32);var launch=new Launcher(station,args[0],args[1],clock);var runtime=new SupervisorRuntime(journal,launch,new WatchdogPolicy(10000,1000,500,256L*1024*1024,1000,1000),1,256L*1024*1024,()=>clock.ElapsedMilliseconds);try{
  foreach(string mode in new[]{"normal","hang","nonzero","wrong","wrong-instance","wrong-generation"}){var task=runtime.Start(new LaunchRequest(Guid.NewGuid(),new string('a',64),Guid.NewGuid(),1,StartIntent.Manual,mode,256L*1024*1024));Until(()=>task.IsCompleted);var session=task.GetAwaiter().GetResult();Until(()=>session.Ready.IsCompleted);session.Ready.GetAwaiter().GetResult();session.Stop();Until(()=>session.Completion.IsCompleted);session.Completion.GetAwaiter().GetResult();var w=launch.Last;Need(w.Cleaned,"all-stop-resources-closed-"+mode);if(mode=="normal")Need(session.GracefulStop&&w.Kills==0&&w.Stop.PublishedAt>=session.StopAcceptedAt&&w.Stop.PublishedAt<=session.ExitedAt&&session.ExitedAt-session.StopAcceptedAt<=500,"normal-stop-without-kill");else {Need(!session.GracefulStop,"error-exit-not-graceful-"+mode);if(mode!="hang")Need(w.Kills==0&&session.ForcedAt<0,"natural-error-exit-not-force-killed-"+mode);if(mode=="hang")Need(session.Fault==FaultReason.StopTimeout&&session.ForcedAt-session.StopAcceptedAt>=500,"unresponsive-gets-full-grace");}var result=session.StopEvidence;result["mode"]=mode;results.Add(result);}
 }finally{runtime.Close();Until(()=>runtime.Completion.IsCompleted);runtime.Completion.GetAwaiter().GetResult();journal.Close();journal.Completion.GetAwaiter().GetResult();}}File.WriteAllText(Path.Combine(args[1],"results.json"),results.ToString());return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
